with v(k,q) as (values ('emergency.0','fire extinguisher location'),('emergency.1','eyewash station'),('emergency.2','first aid kit station'),('emergency.3','emergency assembly point muster'),('visitor.0','visitors check in office'),('visitor.1','authorized personnel only'),('visitor.2','contractor safety orientation'),('employee_only.0','employees only beyond this point'),('ppe.0','hard hat required area'),('ppe.1','safety glasses required'),('ppe.2','hearing protection required'),('ppe.3','high visibility vest required'),('machines.0','machine guard must be in place'),('machines.1','pinch point rotating parts keep hands clear'),('machines.2','authorized operator only machine'),('lockout.0','lockout tagout before servicing equipment'),('lockout.1','lockout tagout station'),('forklift.0','forklift traffic area'),('forklift.1','pedestrian walkway forklift'),('forklift.2','stop look forklift crossing'),('battery.0','forklift battery charging area'),('battery.1','battery charging no open flame hydrogen'),('battery.2','battery room eyewash station')),
r as (select v.k, s.sku, row_number() over (partition by v.k order by s.score desc) rn from v cross join lateral finder.search_ids(v.q,null,null,null,null,10) s)
select r.k, r.rn, c.handle, left(c.title,90) t from r join lateral finder.cards(array[r.sku]) c on true where r.rn<=3 order by r.k, r.rn